// The real MercadiaRoom Durable Object class over a faithful in-memory SQLite `kv`, with authentic v2 fixtures
// generated by the deployed v2 code (b1bab784). `cloudflare:workers` is stubbed; nothing else is mocked.
import { beforeEach, describe, expect, it, vi } from 'vitest';

vi.mock('cloudflare:workers', () => ({
  DurableObject: class {
    ctx: unknown;
    env: unknown;
    constructor(ctx: unknown, env: unknown) {
      this.ctx = ctx;
      this.env = env;
    }
  },
}));

import { LEGACY_ROOM_MESSAGE } from '../src/shared/constants';
import { MercadiaRoom } from '../src/room-do';
import { RoomCore } from '../src/shared/room';
import lobbyRoom from '../tests/fixtures/v2/lobby.room.json?raw';
import runningGame from '../tests/fixtures/v2/running.game.json?raw';
import runningRoom from '../tests/fixtures/v2/running.room.json?raw';

const V2_LOBBY = { room: lobbyRoom, game: null as string | null };
const V2_RUNNING = { room: runningRoom, game: runningGame };

/** An in-memory stand-in for the Durable Object's SQLite storage that records every write. */
function fakeCtx(initial: Record<string, string>) {
  const kv = new Map<string, string>(Object.entries(initial));
  const writes: string[] = [];
  const exec = vi.fn((sql: string, ...args: unknown[]) => {
    const q = sql.trim();
    if (q.startsWith('CREATE TABLE')) return { toArray: () => [] };
    if (q.startsWith('SELECT v FROM kv')) {
      const v = kv.get(args[0] as string);
      return { toArray: () => (v === undefined ? [] : [{ v }]) };
    }
    if (q.startsWith('INSERT INTO kv')) {
      writes.push(`write:${args[0]}`);
      kv.set(args[0] as string, args[1] as string);
      return { toArray: () => [] };
    }
    throw new Error(`unexpected sql: ${sql}`);
  });
  const sockets: unknown[] = [];
  const storage = {
    sql: { exec },
    transactionSync: <T>(fn: () => T): T => fn(),
    setAlarm: vi.fn(async () => {}),
    deleteAll: vi.fn(async () => {
      writes.push('deleteAll');
      kv.clear();
    }),
  };
  const ctx = { storage, getWebSockets: () => sockets, acceptWebSocket: vi.fn() };
  return { ctx, kv, writes, storage };
}

const make = (initial: Record<string, string>) => {
  const f = fakeCtx(initial);
  const room = new MercadiaRoom(f.ctx as never, {} as never);
  return { ...f, room };
};
const snapshot = (kv: Map<string, string>): string => JSON.stringify([...kv.entries()].sort());
const req = (path: string, init: RequestInit & { upgrade?: boolean } = {}): Request =>
  new Request(`https://room${path}`, { method: init.method ?? 'GET', headers: init.upgrade ? { Upgrade: 'websocket' } : {} });

describe.each([
  ['v2 lobby', V2_LOBBY],
  ['v2 running match', V2_RUNNING],
])('MercadiaRoom over an authentic %s', (_name, fixture) => {
  let d: ReturnType<typeof make>;
  let before: string;
  beforeEach(() => {
    const initial: Record<string, string> = { room: fixture.room };
    if (fixture.game) initial.game = fixture.game;
    d = make(initial);
    before = snapshot(d.kv);
  });
  const untouched = (): void => {
    expect(snapshot(d.kv)).toBe(before);
    expect(d.writes).toEqual([]);
    expect(d.storage.deleteAll).not.toHaveBeenCalled();
    expect(d.storage.setAlarm).not.toHaveBeenCalled();
  };

  it('restore() isolates the room: no core, no write, no delete', () => {
    expect((d.room as unknown as { core: unknown }).core).toBeNull();
    expect((d.room as unknown as { legacy: boolean }).legacy).toBe(true);
    untouched();
  });

  it('/summary answers 410 legacy_room', async () => {
    const res = await d.room.fetch(req('/summary'));
    expect(res.status).toBe(410);
    expect(await res.json()).toEqual({ ok: false, legacy: true, code: 'legacy_room', error: LEGACY_ROOM_MESSAGE });
    expect(LEGACY_ROOM_MESSAGE).toBe('This room is from an older MERCADIA version — create a new room to play.');
    untouched();
  });

  it('/export answers 410 legacy_room', async () => {
    const res = await d.room.fetch(req('/export'));
    expect(res.status).toBe(410);
    expect(await res.json()).toEqual({ ok: false, legacy: true, code: 'legacy_room', error: 'Legacy v2 rooms cannot be exported in v3.' });
    untouched();
  });

  it('a WebSocket upgrade answers 410 without accepting a socket', async () => {
    const res = await d.room.fetch(req('/ws/rooms/LEGB', { upgrade: true }));
    expect(res.status).toBe(410);
    expect(d.ctx.acceptWebSocket).not.toHaveBeenCalled();
    untouched();
  });

  it('POST /init answers 409 and never overwrites the v2 storage', async () => {
    const res = await d.room.fetch(req('/init?code=LEGB', { method: 'POST' }));
    expect(res.status).toBe(409);
    expect(await res.json()).toEqual({ ok: false, error: 'Room exists' });
    untouched();
  });

  it('alarm() neither purges, advances, nor reschedules', async () => {
    await d.room.alarm();
    untouched();
    // even long after the idle window, and with no `touched` row at all
    vi.useFakeTimers();
    vi.setSystemTime(Date.now() + 90 * 24 * 3600 * 1000);
    await d.room.alarm();
    vi.useRealTimers();
    untouched();
  });

  it('every route in a row leaves the kv rows byte-for-byte identical', async () => {
    for (const r of [req('/summary'), req('/export'), req('/ws/rooms/LEGB', { upgrade: true }), req('/init?code=LEGB', { method: 'POST' }), req('/nothing')]) await d.room.fetch(r);
    await d.room.alarm();
    expect(snapshot(d.kv)).toBe(before);
    expect(d.kv.get('room')).toBe(fixture.room);
    if (fixture.game) expect(d.kv.get('game')).toBe(fixture.game);
    expect(d.kv.has('touched')).toBe(false);
  });
});

describe('MercadiaRoom over an empty or v3 store', () => {
  it('an empty object creates a room on /init (201), then answers /summary and refuses a second /init', async () => {
    const d = make({});
    expect((d.room as unknown as { legacy: boolean }).legacy).toBe(false);
    expect((await d.room.fetch(req('/summary'))).status).toBe(404);
    expect((await d.room.fetch(req('/init?code=ABCD', { method: 'POST' }))).status).toBe(201);
    expect(d.kv.has('room')).toBe(true);
    expect((await d.room.fetch(req('/summary'))).status).toBe(200);
    expect((await d.room.fetch(req('/init?code=ABCD', { method: 'POST' }))).status).toBe(409);
  });

  it('restores a stored v3 room and serves it', async () => {
    const c = new RoomCore('ABCD', 9);
    const d = make({ room: JSON.stringify(c.room) });
    expect((await d.room.fetch(req('/summary'))).status).toBe(200);
  });
});

