const started = (): RoomCore => {
  const c = new RoomCore('ABCD', 11);
  c.join(null, 'Ada', () => 'p1');
  c.handle('p1', { t: 'start' });
  return c;
};

describe('export guard for matches that started under an older ruleset', () => {
  it('a persisted room without exportVersion keeps playing but is not exported as version 5', async () => {
    const c = started();
    c.handle('p1', { t: 'draft', turn: 1, revision: 1, orders: [{ t: 'borrow' }] });
    c.handle('p1', { t: 'ready', turn: 1, revision: 1, epoch: 0 });
    const { exportVersion: _drop, ...pre } = c.room;
    const d = make({ room: JSON.stringify(pre), game: JSON.stringify(c.game) });
    const res = await d.room.fetch(req('/export'));
    expect(res.status).toBe(409);
    expect(await res.json()).toEqual({ ok: false, code: 'incompatible_ruleset', error: 'This match started under an older ruleset and cannot be exported as version 5.' });
    expect(res.headers.get('content-disposition')).toBeNull();
    expect(d.writes).toEqual([]);
    // still a normal v3 room otherwise
    expect((await d.room.fetch(req('/summary'))).status).toBe(200);
    // an explicit older exportVersion is refused the same way
    const d4 = make({ room: JSON.stringify({ ...pre, exportVersion: 4 }), game: JSON.stringify(c.game) });
    expect((await d4.room.fetch(req('/export'))).status).toBe(409);
  });

  it('a persisted v5 room exports 200 with version 5; an unstarted lobby is 409 without the ruleset code', async () => {
    const c = started();
    const d = make({ room: JSON.stringify(c.room), game: JSON.stringify(c.game) });
    const ok = await d.room.fetch(req('/export'));
    expect(ok.status).toBe(200);
    expect(((await ok.json()) as { version: number }).version).toBe(5);
    const lobby = make({ room: JSON.stringify(new RoomCore('ABCD', 1).room) });
    const res = await lobby.room.fetch(req('/export'));
    expect(res.status).toBe(409);
    expect(await res.json()).toEqual({ ok: false, error: 'The match has not started yet' });
  });

});
